@Test
public void testLoadJsonFromHttp() {
    testCall(db, "CALL apoc.load.json('http://127.0.0.1:8081/test.json') YIELD value RETURN value", (row) -> assertEquals("foo", ((Map)row.get("value")).get("bar")));
}

